import * as THREE from 'three';
import {loadModel, applyShading} from './assets.mjs';

const PALETTE = ['#8a6b45', '#7d6b52', '#6f5a3e', '#7a7f6a', '#6a5f4d', '#9a7b4f', '#5f6a58', '#8b7355'];
const WALL_HEIGHT = 2.8;
const CURB_HEIGHT = 0.25;

// Builds the renderer, the room shell and every furniture anchor from layout.json
// (generated by scripts/build-layout.mjs; coordinates are room-local metres).
export async function createWorld(layout) {
  const renderer = new THREE.WebGLRenderer({antialias: true});
  renderer.setPixelRatio(Math.min(devicePixelRatio, 1.5));
  renderer.setSize(innerWidth, innerHeight);
  renderer.shadowMap.enabled = true;
  renderer.shadowMap.type = THREE.PCFSoftShadowMap;
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;
  document.body.appendChild(renderer.domElement);

  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#0b0e0b');

  const room = layout.room;
  const bounds = {minX: room.minX, maxX: room.maxX, minZ: room.minZ, maxZ: room.maxZ};
  const width = bounds.maxX - bounds.minX;
  const depth = bounds.maxZ - bounds.minZ;
  const center = new THREE.Vector3((bounds.minX + bounds.maxX) / 2, 0, (bounds.minZ + bounds.maxZ) / 2);

  const floor = new THREE.Mesh(
    new THREE.PlaneGeometry(width, depth),
    new THREE.MeshStandardMaterial({color: '#4a4238', roughness: 0.96}),
  );
  floor.rotation.x = -Math.PI / 2;
  floor.position.set(center.x, 0, center.z);
  floor.receiveShadow = true;
  scene.add(floor);

  // Rug under the bed, as in the original bedroom (shell prefab G_Carpet_013).
  const bed = layout.anchors.find((a) => a.id === 9104);
  if (bed) {
    const rug = new THREE.Mesh(new THREE.PlaneGeometry(2.8, 3.4), new THREE.MeshStandardMaterial({color: '#5b5240', roughness: 1}));
    rug.rotation.x = -Math.PI / 2;
    rug.position.set(bed.x, 0.005, bed.z + 0.3);
    rug.receiveShadow = true;
    scene.add(rug);
  }

  // The isometric camera looks toward -x/-z, so west and north are the back walls
  // (full height, like the original's picture wall); east and south stay low so they
  // mark the boundary without hiding the room.
  const wallMat = new THREE.MeshStandardMaterial({color: '#6b5f48', roughness: 0.92});
  const curbMat = new THREE.MeshStandardMaterial({color: '#3d372d', roughness: 0.92});
  const addWall = (x, z, w, d, h, material) => {
    const wall = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), material);
    wall.position.set(x, h / 2, z);
    wall.receiveShadow = true;
    wall.castShadow = h > 1;
    scene.add(wall);
  };
  const T = 0.12;
  addWall(center.x, bounds.minZ - T / 2, width + 2 * T, T, WALL_HEIGHT, wallMat);
  addWall(bounds.minX - T / 2, center.z, T, depth, WALL_HEIGHT, wallMat);
  addWall(bounds.maxX + T / 2, center.z, T, depth, CURB_HEIGHT, curbMat);
  addWall(center.x, bounds.maxZ + T / 2, width + 2 * T, T, CURB_HEIGHT, curbMat);

  scene.add(new THREE.HemisphereLight('#aebfd8', '#33322a', 1.0));
  const key = new THREE.DirectionalLight('#ffd9a8', 2.6);
  key.position.set(center.x + 6, 9, center.z + 5);
  key.castShadow = true;
  key.shadow.mapSize.set(1024, 1024);
  key.shadow.camera.left = -12; key.shadow.camera.right = 12;
  key.shadow.camera.top = 12; key.shadow.camera.bottom = -12;
  scene.add(key);
  const fill = new THREE.DirectionalLight('#8fa6c4', 0.8);
  fill.position.set(bounds.minX - 5, 6, bounds.maxZ + 4);
  scene.add(fill);
  // Bedside lamp glow (shell prefab G_Lamp_004 sits on the nightstand).
  const stand = layout.anchors.find((a) => a.id === 9109);
  if (stand) {
    const lamp = new THREE.PointLight('#ffc27a', 6, 5, 1.6);
    lamp.position.set(stand.x, 1.3, stand.z);
    scene.add(lamp);
  }

  const solids = [];
  // Static shell props that are not interactive (inferred sizes, see layout.props).
  for (const prop of layout.props ?? []) {
    const [w, h, d] = prop.size;
    const geometry = prop.round ? new THREE.CylinderGeometry(w / 2, w / 2.6, h, 20) : new THREE.BoxGeometry(w, h, d);
    const mesh = new THREE.Mesh(geometry, new THREE.MeshStandardMaterial({color: '#6a5034', roughness: 0.8}));
    mesh.position.set(prop.x, h / 2, prop.z);
    mesh.castShadow = true;
    scene.add(mesh);
    if (prop.solid) solids.push({minX: prop.x - w / 2, maxX: prop.x + w / 2, minZ: prop.z - d / 2, maxZ: prop.z + d / 2, name: prop.name});
  }

  const anchors = [];
  let index = 0;
  for (const anchor of layout.anchors) {
    const point = new THREE.Vector3(anchor.x, anchor.y ?? 0, anchor.z);
    let object = anchor.model ? await loadModel(anchor.model) : null;
    let tinted = true;
    if (!object) {
      // Placeholder footprint until that prefab is exported.
      const [w, h, d] = anchor.placeholder?.size ?? [0.5, 0.5, 0.5];
      object = new THREE.Group();
      const box = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), new THREE.MeshStandardMaterial({color: anchor.placeholder?.color ?? '#4a5244', roughness: 0.9}));
      box.position.y = h / 2;
      box.castShadow = true;
      object.add(box);
      tinted = false;
    }
    if (tinted) applyShading(object, new THREE.Color(PALETTE[index % PALETTE.length]));
    object.userData.anchorId = anchor.id;
    object.position.copy(point);
    // Mesh export mirrors x; PI - unityYaw maps it back into the room frame.
    object.rotation.y = Math.PI - THREE.MathUtils.degToRad(anchor.unityYawDeg ?? 0);
    scene.add(object);

    const box3 = new THREE.Box3().setFromObject(object);
    const box = Number.isFinite(box3.min.x)
      ? {minX: box3.min.x, maxX: box3.max.x, minZ: box3.min.z, maxZ: box3.max.z}
      : {minX: point.x - 0.3, maxX: point.x + 0.3, minZ: point.z - 0.3, maxZ: point.z + 0.3};
    const solid = anchor.solid === false ? null : {...box, name: anchor.name};
    if (solid) solids.push(solid);
    anchors.push({id: anchor.id, name: anchor.name, point, box, object, solid, kind: null});
    index += 1;
  }

  const spawn = layout.spawn ? {x: layout.spawn.x, z: layout.spawn.z} : null;
  return {renderer, scene, bounds, width, depth, center, anchors, solids, spawn};
}
